function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 200000) return 'nums needs 1 to 200000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value is a whole number between 0 and 10^9.';
  if (!Number.isInteger(k) || k < 0 || k > 1000000000) return 'k is a whole number between 0 and 10^9.';
