function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    // Each value has one or two set bits, with high bits rare, and k needs several of the high bits at once,
    // so the shortest qualifying window is usually long.
    const n = 2000;
    const bitOf = () => Math.floor(30 * Math.pow(rand(), 2));
    const nums = Array.from({ length: n }, () => (rand() < 0.7 ? 1 << bitOf() : (1 << bitOf()) | (1 << bitOf())));
    let k = 0;
    const need = int(2, 6);
    for (let i = 0; i < need; i++) k |= 1 << (29 - i);
    return [nums, Math.min(k - int(0, 1), 1000000000)];
  }
  const n = int(1, 8);
  const top = rand() < 0.7 ? 15 : 1000000000;
  const nums = Array.from({ length: n }, () => (rand() < 0.2 ? 0 : int(0, top)));
  const k = rand() < 0.15 ? 0 : int(0, top === 15 ? 20 : 1000000000);
